          { title: "\u653F\u7B56\u8B8A\u66F4\u8207\u806F\u7E6B", paragraphs: ["\u6211\u5011\u53EF\u80FD\u56E0\u696D\u52D9\u3001\u6CD5\u5F8B\u6216\u6280\u8853\u8B8A\u5316\u66F4\u65B0\u672C\u653F\u7B56\uFF0C\u4E26\u5728\u672C\u9801\u9762\u767C\u4F48\u65B0\u7248\u672C\u3002\u5982\u6709\u7591\u554F\uFF0C\u8BF7\u806F\u7E6B support@shopark.ai\u3002"] }
